css.vlak:
/* ═══════════════════════════════════════════════════════════════════
   VLAK, a minimal, CSS-first design system.
   https://vlak.dev

   One ink, no accent hue: emphasis comes from weight, size, and
   spacing. Hairline borders, a 204px module grid (184px column +
   20px gutter), sentence case everywhere.

   Layers: vlak.tokens, vlak.base, vlak.type, vlak.components, vlak.touch, vlak.motion.
   Your own unlayered CSS overrides any of it by default.

   GENERATED from the css/ sources. Edit those, then run
   `npm run build:css`. Tokens come from src/tokens.ts.

   Typeface: Inter (SIL OFL 1.1), variable, latin + latin-ext.
   Bundled. System sans is fallback only.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Inter ── SIL OFL 1.1. Variable, latin + latin-ext.
   System sans is fallback only (see body in base.css). */
@font-face{
  font-family:Inter;
  font-style:normal;
  font-weight:100 900;
  font-display:swap;
  src:url("./fonts/inter/InterVariable-latin-ext.woff2") format("woff2");
  unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF
}
@font-face{
  font-family:Inter;
  font-style:normal;
  font-weight:100 900;
  font-display:swap;
  src:url("./fonts/inter/InterVariable-latin.woff2") format("woff2");
  unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD
}

@layer vlak.tokens, vlak.base, vlak.type, vlak.components, vlak.touch, vlak.motion;

@layer vlak.tokens {
/* ── Tokens ── GENERATED from src/tokens.ts. Do not edit by hand. */
:root {
  --bg: #FAF8F2;                        /* paper */
  --text: #1A1A1A;                      /* ink */
  --text-secondary: #6B6B6B;            /* gray */
  --accent: #1A1A1A;                   /* the "accent" is ink; monochrome */
  --divider: rgba(0,0,0,0.08);
  --divider-subtle: rgba(0,0,0,0.06);
  --table-alt: rgba(0,0,0,0.02);
  --grid-line: rgba(0,0,0,0.04);
  --control-border: rgba(0,0,0,0.42);
  --control-fill: #E4E2DC;
  color-scheme: light;
  --radius-sm: 4px;           /* slight Vlak radius; standalone buttons */
  --radius: var(--radius-sm);              /* alias — buttons, boxes, dialogs share it; cards stay 0 */
  --radius-chrome: 0px;
  --gutter: 20px;
  --pad: 20px;
  /* Concentric: Steve Ruiz innerRadius result. Closed form of the circular-corner fit. Default radius vs --pad is 0. */
  --radius-in: max(0px, calc(var(--radius) - var(--pad)));
  --ease: cubic-bezier(0.3, 0, 0.2, 1);
  --duration-snap: 0.1s;
  --duration: 0.2s;
  --duration-deliberate: 0.4s;
  --duration-confirm: 0.3s;
  /* The hover transition every control shares: fill, edge, ink, opacity. */
  --transition: background-color var(--duration) var(--ease), border-color var(--duration) var(--ease), color var(--duration) var(--ease), opacity var(--duration) var(--ease);
  /* Background column grid: 204px modules (184 column + 20 gutter). */
  --grid-image: linear-gradient(to right,var(--grid-line) 0,var(--grid-line) 1px,transparent 1px,transparent 184px,var(--grid-line) 184px,var(--grid-line) 185px,transparent 185px,transparent 204px);
  --grid-size: 204px;
  --grid-pos: 20px 0;
  --text-scale: 1;
  /* Stacking scale. Native dialog and popover use the top layer instead. */
  --z-raised: 10;
  --z-sticky: 100;
  --z-float: 200;
  --z-overlay: 300;
  --z-toast: 400;
  /* Contract variables a component may set inline: concentric radius and the chart spot color. */
  --rs-out: var(--radius);
  --rs-gap: var(--pad);
  --rs-in: var(--radius-in);
  --rs-chart-spot: var(--text);
  /* Control scale. Every interactive target is at least 44px; phone fields use 16px type. */
  --hit: 2.75rem;
  --control-h: 2.75rem;
  --control-fs: 0.875rem;
  --control-label: 0.75rem;
}
[data-theme="dark"] {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  --control-fill: #242220;
  color-scheme: dark;
}
/* System dark scheme applies until the page decides with data-theme. */
@media (prefers-color-scheme: dark) {
:root:not([data-theme="light"]) {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  --control-fill: #242220;
  color-scheme: dark;
}
}
/* Mobile grid (≤480): two fluid columns, three 25px gutters
   (edge · middle · edge). Column width = 50vw − 37.5px; the background
   draws all four column-edge lines and content lives between the outer pair. */
@media(max-width:480px){
  :root{
    --pad:25px;
    --grid-image:linear-gradient(to right,transparent 0,transparent 25px,var(--grid-line) 25px,var(--grid-line) 26px,transparent 26px,transparent calc(50vw - 12.5px),var(--grid-line) calc(50vw - 12.5px),var(--grid-line) calc(50vw - 11.5px),transparent calc(50vw - 11.5px),transparent calc(50vw + 12.5px),var(--grid-line) calc(50vw + 12.5px),var(--grid-line) calc(50vw + 13.5px),transparent calc(50vw + 13.5px),transparent calc(100vw - 26px),var(--grid-line) calc(100vw - 26px),var(--grid-line) calc(100vw - 25px),transparent calc(100vw - 25px));
    --grid-size:100vw;
    --grid-pos:0 0;
  }
}
/* Phone control scale (≤640): keep 44px hits and use 16px type on fields. */
@media(max-width:640px){
  :root{
    --hit:2.75rem;
    --control-h:2.75rem;
    --control-fs:1rem;
    --control-label:0.9375rem;
  }
}

}

@layer vlak.base {
/* ── Base ──
   Vlak owns the page: paper on html, ink on body, and quiet
   gutter verticals on html::before so overflow-x:clip cannot drop
   them. --grid-pos: 20px 0 puts the first tile line on the left
   20px gutter; that utmost left gutter must paint. Do not clip
   it. No 204 horizontals — those cage the type. Homepage and
   About kill this overlay and keep boxed cells only. */
/* --text-scale multiplies the root size, so every rem in the system (type,
   controls, spacing inside components) follows it while the px module grid
   stays put. Browser text settings still apply underneath. */
html{scroll-behavior:smooth;overflow-x:clip;background-color:var(--bg);font-size:calc(100% * var(--text-scale, 1))}
html::before{
  content:"";
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100%;
  background-repeat:repeat-x;
  background-position:var(--grid-pos)
}
body{
  position:relative;
  z-index:1;
  overflow-x:clip;
  background-color:transparent;
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.45;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.rs-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

}

@layer vlak.type {
/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps.
   Sizes are rem: --text-scale on the root scales them with everything else. */
.rs-t-xl{font-size:clamp(2.125rem,5vw,3.25rem);font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:2.375rem;font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:1.375rem;font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:1.0625rem;font-weight:500;letter-spacing:-.01em;line-height:1.45;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:0.9375rem;font-weight:500;letter-spacing:-.01em;line-height:1.45;color:var(--text);margin:0;max-width:66ch;text-wrap:pretty}
.rs-t-label{font-size:0.8125rem;font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.rs-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

}

@layer vlak.components {
.rs-ios-navigation-bar{box-sizing:border-box;font-family:Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;color:var(--text);min-width:0;padding:8px}
.rs-ios-navigation-bar-vertical{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:0}
.rs-ios-navigation-bar-row{display:grid;grid-template-columns:minmax(48px, 1fr) minmax(0, auto) minmax(48px, 1fr);gap:8px;align-items:center;min-height:54px}
.rs-ios-navigation-bar-leading{justify-self:start}
.rs-ios-navigation-bar-actions{display:inline-flex;align-items:center;gap:2px;padding:3px;border-radius:27px;justify-self:end;background-color:var(--control-fill);border-width:1px;border-style:solid;border-color:var(--control-border)}
@media (forced-colors: active){.rs-ios-navigation-bar-actions{border-color:ButtonText}}
.rs-ios-navigation-bar-rail{display:flex;flex-direction:column;align-items:center;gap:12px;flex-shrink:0}
.rs-ios-navigation-bar-actions-vertical{flex-direction:column}
.rs-ios-navigation-bar-button{appearance:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;box-sizing:border-box;min-width:44px;min-height:44px;padding-block:10px;padding-inline:12px;border-width:0;border-radius:22px;background-color:transparent;color:var(--text);font-family:Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;font-size:17px;line-height:22px;cursor:pointer;outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:-2px;transition:background-color 200ms ease}
.rs-ios-navigation-bar-button:focus-visible{outline-width:2px}
@media (hover: hover) and (pointer: fine){.rs-ios-navigation-bar-button:hover{background-color:var(--bg)}}
@media (prefers-reduced-motion: reduce){.rs-ios-navigation-bar-button{transition:none}}
.rs-ios-navigation-bar-icon-button{width:44px;padding:0}
.rs-ios-navigation-bar-back{min-width:48px;min-height:48px;width:48px;border-radius:24px;padding:0;background-color:var(--control-fill);border-width:1px;border-style:solid;border-color:var(--control-border)}
@media (forced-colors: active){.rs-ios-navigation-bar-back{border-color:ButtonText}}
.rs-ios-navigation-bar-disabled{opacity:0.45;cursor:not-allowed}
.rs-ios-navigation-bar-title{margin:0;text-align:center;font-size:17px;line-height:22px;font-weight:600;overflow-wrap:anywhere}
.rs-ios-navigation-bar-large-title{margin-block:10px 4px;margin-inline:8px;font-size:34px;line-height:41px;letter-spacing:-0.035em;text-align:start;font-weight:700}
.rs-ios-navigation-bar-vertical-title{text-align:start;font-size:28px;line-height:34px;font-weight:700;margin-block:8px;margin-inline:0}

.rs-ios-tab-bar{display:inline-flex;box-sizing:border-box;align-items:stretch;gap:2px;padding:6px;max-width:100%;min-height:62px;overflow-x:auto;border-radius:31px;border-width:1px;border-style:solid;border-color:var(--control-border);background-color:var(--control-fill);color:var(--text);font-family:Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif}
@media (forced-colors: active){.rs-ios-tab-bar{border-color:ButtonText}}
.rs-ios-tab-bar-vertical{flex-direction:column;width:62px;min-width:62px;max-height:100%;overflow-y:auto;overflow-x:hidden;min-height:0}
.rs-ios-tab-bar-tab{appearance:none;display:flex;flex-direction:column;align-items:center;justify-content:center;flex:1 0 48px;gap:2px;min-width:48px;min-height:48px;box-sizing:border-box;padding-block:4px;padding-inline:12px;border-radius:24px;border-width:0;background-color:transparent;color:var(--text);font-family:inherit;font-size:11px;line-height:14px;font-weight:500;cursor:pointer;outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:-2px;transition:background-color 200ms ease, color 200ms ease}
.rs-ios-tab-bar-tab:focus-visible{outline-width:2px}
@media (hover: hover) and (pointer: fine){.rs-ios-tab-bar-tab:hover{background-color:var(--bg)}}
@media (prefers-reduced-motion: reduce){.rs-ios-tab-bar-tab{transition:none}}
.rs-ios-tab-bar-active{color:var(--text);background-color:var(--bg);font-weight:600;forced-color-adjust:none}
@media (forced-colors: active){.rs-ios-tab-bar-active{color:HighlightText;background-color:Highlight}}
.rs-ios-tab-bar-disabled{opacity:0.45;cursor:not-allowed}
.rs-ios-tab-bar-symbol{display:inline-flex;width:24px;height:24px;align-items:center;justify-content:center}
.rs-ios-tab-bar-tab-vertical{padding:0;flex:0 0 48px}
.rs-ios-tab-bar-vertical-label{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}

.rs-ios-search-field{display:flex;align-items:center;gap:8px;box-sizing:border-box;min-width:0;min-height:48px;width:100%;padding-inline-start:16px;padding-inline-end:2px;border-radius:24px;border-width:1px;border-style:solid;border-color:var(--control-border);background-color:var(--control-fill);color:var(--text-secondary);outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:2px}
.rs-ios-search-field:focus-within{outline-width:2px}
@media (forced-colors: active){.rs-ios-search-field{border-color:ButtonText}}
.rs-ios-search-field-disabled{opacity:0.45}
.rs-ios-search-field-symbol{display:inline-flex;flex-shrink:0;pointer-events:none}
.rs-ios-search-field-input{appearance:none;font-family:Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;font-size:17px;line-height:22px;color:var(--text);width:100%;min-width:0;min-height:44px;flex-grow:1;border-width:0;background-color:transparent;padding-block:10px;padding-inline:0;margin:0;outline-width:0}
.rs-ios-search-field-input::placeholder{color:var(--text);opacity:1}
.rs-ios-search-field-input::-webkit-search-cancel-button{appearance:none}
.rs-ios-search-field-clear{appearance:none;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;min-width:44px;min-height:44px;border-radius:22px;border-width:0;padding:0;background-color:transparent;color:var(--text-secondary);cursor:pointer;outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:-3px;transition:background-color 200ms ease}
.rs-ios-search-field-clear:focus-visible{outline-width:2px}
@media (hover: hover) and (pointer: fine){.rs-ios-search-field-clear:hover{background-color:var(--bg)}}
@media (prefers-reduced-motion: reduce){.rs-ios-search-field-clear{transition:none}}

.rs-ios-switch{display:inline-flex;position:relative;align-items:center;width:64px;min-width:64px;height:44px;min-height:44px;vertical-align:middle;flex-shrink:0;border-radius:22px;outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:2px}
.rs-ios-switch:focus-within{outline-width:2px}
.rs-ios-switch-disabled{opacity:0.45}
.rs-ios-switch-track{position:absolute;inset-inline:0;top:8px;height:28px;border-radius:14px;box-sizing:border-box;border-width:1px;border-style:solid;border-color:var(--control-border);background-color:var(--control-fill);pointer-events:none;transition:background-color 220ms ease}
@media (forced-colors: active){.rs-ios-switch-track{border-color:ButtonText;background-color:Canvas}}
@media (prefers-reduced-motion: reduce){.rs-ios-switch-track{transition:none}}
.rs-ios-switch-on{background-color:var(--text);border-color:var(--text);forced-color-adjust:none}
@media (forced-colors: active){.rs-ios-switch-on{background-color:Highlight;border-color:Highlight}}
.rs-ios-switch-thumb{position:absolute;top:10px;inset-inline-start:2px;height:24px;width:38px;border-radius:12px;box-sizing:border-box;border-width:1px;border-style:solid;border-color:var(--control-border);background-color:var(--bg);pointer-events:none;transition:inset-inline-start 220ms cubic-bezier(.2,.8,.2,1)}
@media (forced-colors: active){.rs-ios-switch-thumb{border-color:ButtonText;background-color:Canvas}}
@media (prefers-reduced-motion: reduce){.rs-ios-switch-thumb{transition:none}}
.rs-ios-switch-thumb-on{inset-inline-start:24px;border-color:transparent;background-color:var(--bg);forced-color-adjust:none}
@media (forced-colors: active){.rs-ios-switch-thumb-on{background-color:HighlightText}}
.rs-ios-switch-input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer}
.rs-ios-switch-input:disabled{cursor:not-allowed}

.rs-ios-list{font-family:Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;font-size:17px;line-height:22px;color:var(--text);min-width:0}
.rs-ios-list-title{margin-block:0 8px;margin-inline:16px;font-size:15px;line-height:20px;font-weight:400;color:var(--text-secondary)}
.rs-ios-list-group{border-radius:22px;background-color:var(--bg);border-width:1px;border-style:solid;border-color:var(--divider);overflow:hidden}
@media (forced-colors: active){.rs-ios-list-group{border-color:ButtonText}}
.rs-ios-list-footer{margin-block:8px 0;margin-inline:16px;font-size:13px;line-height:18px;color:var(--text-secondary)}
.rs-ios-list-row{appearance:none;display:flex;align-items:center;box-sizing:border-box;gap:12px;width:100%;min-width:44px;min-height:52px;border-width:0;border-style:solid;border-block-end-width:1px;border-color:var(--divider);background-color:transparent;color:var(--text);padding-block:8px;padding-inline:16px;text-align:start;font-family:inherit;font-size:inherit;line-height:inherit}
.rs-ios-list-row:last-child{border-block-end-width:0}
.rs-ios-list-row-action{cursor:pointer;background-color:transparent;outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:-3px;transition:background-color 200ms ease}
.rs-ios-list-row-action:focus-visible{outline-width:2px}
@media (hover: hover) and (pointer: fine){.rs-ios-list-row-action:hover{background-color:var(--table-alt)}}
@media (prefers-reduced-motion: reduce){.rs-ios-list-row-action{transition:none}}
.rs-ios-list-row-disabled{opacity:0.45;cursor:not-allowed}
.rs-ios-list-row-leading{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;width:28px;min-height:28px}
.rs-ios-list-row-copy{display:flex;flex-direction:column;gap:2px;flex-grow:1;min-width:0;overflow-wrap:anywhere}
.rs-ios-list-row-description{font-size:15px;line-height:20px;color:var(--text-secondary)}
.rs-ios-list-row-trailing{display:inline-flex;align-items:center;gap:8px;color:var(--text-secondary);font-size:15px;line-height:20px;flex-shrink:0}

.rs-ios-segmented-control{display:inline-flex;align-items:stretch;box-sizing:border-box;gap:2px;padding:3px;min-height:50px;max-width:100%;overflow-x:auto;font-family:Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;border-radius:25px;background-color:var(--control-fill);border-width:1px;border-style:solid;border-color:var(--control-border)}
@media (forced-colors: active){.rs-ios-segmented-control{border-color:ButtonText}}
.rs-ios-segmented-control-item{appearance:none;display:inline-flex;align-items:center;justify-content:center;flex:1 0 auto;min-width:44px;min-height:44px;box-sizing:border-box;padding-block:10px;padding-inline:16px;border-width:0;border-radius:22px;background-color:transparent;color:var(--text);font-family:inherit;font-size:15px;line-height:20px;font-weight:500;cursor:pointer;outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:-2px;transition:background-color 220ms ease, color 220ms ease}
.rs-ios-segmented-control-item:focus-visible{outline-width:2px}
@media (hover: hover) and (pointer: fine){.rs-ios-segmented-control-item:hover{background-color:var(--bg)}}
@media (prefers-reduced-motion: reduce){.rs-ios-segmented-control-item{transition:none}}
.rs-ios-segmented-control-selected{color:var(--text);background-color:var(--bg);font-weight:600;forced-color-adjust:none}
@media (forced-colors: active){.rs-ios-segmented-control-selected{color:HighlightText;background-color:Highlight}}
.rs-ios-segmented-control-disabled{opacity:0.45;cursor:not-allowed}

.rs-ios-slider{position:relative;display:block;min-width:44px;width:100%;height:44px;border-radius:22px;outline-width:0;outline-style:solid;outline-color:var(--text);outline-offset:2px}
