	},
	close: {
		appearance: "none",
		float: "inline-end",
		display: "inline-flex",
		alignItems: "center",
		justifyContent: "center",
		width: 48,
		height: 48,
		margin: "-4px -12px 4px 8px",
		padding: 12,
		borderWidth: 0,
		borderRadius: "50%",
		color: vlak.ink,
