export interface AndroidSheetProps
	extends Omit<
		React.DialogHTMLAttributes<HTMLDialogElement>,
		"open" | "onClose"
	> {
	open?: boolean;
	defaultOpen?: boolean;
	onOpenChange?: (open: boolean) => void;
	onClose?: () => void;
	dismissable?: boolean;
	lightDismiss?: boolean;
	closeLabel?: string;
}
export const AndroidSheet = React.forwardRef<
	HTMLDialogElement,
	AndroidSheetProps
>(function AndroidSheet(
	{
		open,
		defaultOpen = false,
		onOpenChange,
		onClose,
		dismissable = true,
		lightDismiss = true,
		closeLabel = "Close",
		className,
		style,
		children,
		...props
	},
	forwardedRef,
) {
	const [inner, setInner] = React.useState(defaultOpen);
	const current = open ?? inner;
	const close = () => {
		if (open === undefined) setInner(false);
		onOpenChange?.(false);
		onClose?.();
	};
	const { ref, context, dialogProps } = useNativeDialog(
		{ open: current, onClose: close, dismissable, lightDismiss },
		props,
