"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Badge } from "./badge";
import { Collapsible } from "./collapsible";
import { CodeBlock } from "./code-block";
import { JSONViewer } from "./json-viewer";

export interface AgentToolDefinition { name: string; description?: string; inputSchema?: unknown }
export interface AgentProps extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  name: string;
  model?: string;
  instructions?: React.ReactNode;
  tools?: AgentToolDefinition[];
  outputSchema?: unknown;
  /** Optional rich/schema renderer. The default safely displays objects or escaped source text. */
  renderSchema?: (schema: unknown, context: "input" | "output") => React.ReactNode;
}
const styles = stylex.create({
  root: { minWidth: 0, width: "100%", borderWidth: vlak.hairline, borderStyle: "solid", borderColor: { default: vlak.divider, [mq.forcedColors]: "CanvasText" }, borderRadius: vlak.radiusSm, color: vlak.ink, backgroundColor: vlak.paper, fontSize: "0.875rem", lineHeight: 1.45 },
  header: { display: "flex", flexWrap: "wrap", alignItems: "center", gap: "0.75rem", padding: "1rem", borderBottomWidth: vlak.hairline, borderBottomStyle: "solid", borderBottomColor: vlak.divider },
  title: { fontWeight: 600, overflowWrap: "anywhere" },
  content: { display: "grid", gap: "1rem", padding: "1rem", minWidth: 0 },
  section: { display: "grid", gap: "0.5rem", minWidth: 0 },
  label: { fontSize: "0.75rem", color: vlak.gray, fontWeight: 600 },
  instructions: { whiteSpace: "pre-wrap", overflowWrap: "anywhere", minWidth: 0 },
  description: { color: vlak.gray, margin: "0 0 0.75rem", overflowWrap: "anywhere" },
});

/** Inspect agent configuration without instantiating tools or executing instructions. */
export const Agent = React.forwardRef<HTMLElement, AgentProps>(function Agent({ name, model, instructions, tools = [], outputSchema, renderSchema, children, className, style, ...props }, ref) {
  const root = rs(["rs-agent", className], styles.root);
  const header = rs(["rs-agent-header"], styles.header);
  const title = rs(["rs-agent-title"], styles.title);
  const content = rs(["rs-agent-content"], styles.content);
  const section = rs(["rs-agent-section"], styles.section);
  const label = rs(["rs-agent-label"], styles.label);
  const instructionsStyle = rs(["rs-agent-instructions"], styles.instructions);
  const description = rs(["rs-agent-description"], styles.description);
  const schema = (value: unknown, context: "input" | "output") => renderSchema ? renderSchema(value, context) : typeof value === "string" ? <CodeBlock code={value} language={context === "output" ? "TypeScript" : "JSON"} /> : <JSONViewer data={value} label={`${context === "input" ? "Input" : "Output"} schema`} searchable={false} />;
  return <article aria-label={`Agent ${name}`} {...props} ref={ref} className={root.className} style={{ ...root.style, ...style }}>
    <header {...header}><span {...title}>{name}</span>{model && <Badge variant="muted">{model}</Badge>}</header>
    <div {...content}>{instructions != null && <div {...section}><span {...label}>Instructions</span><div {...instructionsStyle}>{instructions}</div></div>}
      {tools.length > 0 && <div {...section}><span {...label}>Tools ({tools.length})</span>{tools.map(tool => <Collapsible key={tool.name} title={tool.name}>{tool.description && <p {...description}>{tool.description}</p>}{tool.inputSchema !== undefined ? schema(tool.inputSchema, "input") : <p {...description}>No input schema supplied.</p>}</Collapsible>)}</div>}
      {outputSchema !== undefined && <div {...section}><span {...label}>Output schema</span>{schema(outputSchema, "output")}</div>}{children}
    </div>
  </article>;
});

/* ── agent: generated from packages/react/src/components/agent.tsx ── */
.rs-agent{min-width:0;width:100%;border-width:1px;border-style:solid;border-color:var(--divider);border-radius:var(--radius-sm);color:var(--text);background-color:var(--bg);font-size:0.875rem;line-height:1.45}
@media (forced-colors: active){.rs-agent{border-color:CanvasText}}
.rs-agent-header{display:flex;flex-wrap:wrap;align-items:center;gap:0.75rem;padding:1rem;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider)}
.rs-agent-title{font-weight:600;overflow-wrap:anywhere}
.rs-agent-content{display:grid;gap:1rem;padding:1rem;min-width:0}
.rs-agent-section{display:grid;gap:0.5rem;min-width:0}
.rs-agent-label{font-size:0.75rem;color:var(--text-secondary);font-weight:600}
.rs-agent-instructions{white-space:pre-wrap;overflow-wrap:anywhere;min-width:0}
.rs-agent-description{color:var(--text-secondary);margin:0 0 0.75rem;overflow-wrap:anywhere}

"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Button } from "./button";
import { Icon } from "./icons";

export interface ArtifactProps extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  title: React.ReactNode;
  description?: React.ReactNode;
  actions?: React.ReactNode;
  footer?: React.ReactNode;
  /** Requests closing; the application owns visibility and focus restoration. */
  onClose?: () => void;
  closeLabel?: string;
  /** Optional height cap for long generated content. */
  maxHeight?: React.CSSProperties["maxHeight"];
}
const styles = stylex.create({
  root: { display: "flex", flexDirection: "column", minWidth: 0, width: "100%", borderWidth: vlak.hairline, borderStyle: "solid", borderColor: { default: vlak.divider, [mq.forcedColors]: "CanvasText" }, borderRadius: vlak.radiusSm, color: vlak.ink, backgroundColor: vlak.paper },
  header: { display: "flex", alignItems: "center", flexWrap: "wrap", gap: "0.75rem", padding: "0.75rem 1rem", borderBottomWidth: vlak.hairline, borderBottomStyle: "solid", borderBottomColor: vlak.divider },
  heading: { display: "grid", gap: "0.25rem", minWidth: 0, flex: "1 1 auto", overflowWrap: "anywhere" },
  title: { fontSize: "0.875rem", fontWeight: 600, lineHeight: 1.45 },
  description: { fontSize: "0.75rem", lineHeight: 1.45, color: vlak.gray },
  actions: { display: "flex", flexWrap: "wrap", alignItems: "center", gap: "0.25rem" },
  content: { minWidth: 0, overflow: "auto", padding: "1rem", fontSize: "0.875rem", lineHeight: 1.45, outlineColor: vlak.ink, outlineOffset: -2 },
  footer: { padding: "0.75rem 1rem", borderTopWidth: vlak.hairline, borderTopStyle: "solid", borderTopColor: vlak.divider, color: vlak.gray, fontSize: "0.75rem", lineHeight: 1.45 },
});

/** Generated content with header actions, a close request and an optional scroll region. */
export const Artifact = React.forwardRef<HTMLElement, ArtifactProps>(function Artifact({ title, description, actions, footer, onClose, closeLabel = "Close artifact", maxHeight, children, className, style, "aria-label": label, "aria-labelledby": labelledBy, ...props }, ref) {
  const titleId = React.useId();
  const root = rs(["rs-artifact", className], styles.root);
  const header = rs(["rs-artifact-header"], styles.header);
  const heading = rs(["rs-artifact-heading"], styles.heading);
  const titleStyle = rs(["rs-artifact-title"], styles.title);
  const descriptionStyle = rs(["rs-artifact-description"], styles.description);
  const actionStyle = rs(["rs-artifact-actions"], styles.actions);
  const content = rs(["rs-artifact-content"], styles.content);
  const footerStyle = rs(["rs-artifact-footer"], styles.footer);
  return <section {...props} ref={ref} aria-label={label} aria-labelledby={labelledBy ?? (label == null ? titleId : undefined)} className={root.className} style={{ ...root.style, ...style }}>
    <header {...header}><div {...heading}><span {...titleStyle} id={titleId}>{title}</span>{description != null && <div {...descriptionStyle}>{description}</div>}</div>
      {(actions != null || onClose) && <div {...actionStyle}>{actions}{onClose && <Button type="button" variant="subtle" size="icon" aria-label={closeLabel} title={closeLabel} onClick={onClose}><Icon name="close" /></Button>}</div>}
    </header>
    <div className={content.className} style={{ ...content.style, maxHeight }} tabIndex={maxHeight != null ? 0 : undefined}>{children}</div>
    {footer != null && <footer {...footerStyle}>{footer}</footer>}
  </section>;
});

/* ── artifact: generated from packages/react/src/components/artifact.tsx ── */
.rs-artifact{display:flex;flex-direction:column;min-width:0;width:100%;border-width:1px;border-style:solid;border-color:var(--divider);border-radius:var(--radius-sm);color:var(--text);background-color:var(--bg)}
@media (forced-colors: active){.rs-artifact{border-color:CanvasText}}
.rs-artifact-header{display:flex;align-items:center;flex-wrap:wrap;gap:0.75rem;padding:0.75rem 1rem;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider)}
.rs-artifact-heading{display:grid;gap:0.25rem;min-width:0;flex:1 1 auto;overflow-wrap:anywhere}
.rs-artifact-title{font-size:0.875rem;font-weight:600;line-height:1.45}
.rs-artifact-description{font-size:0.75rem;line-height:1.45;color:var(--text-secondary)}
.rs-artifact-actions{display:flex;flex-wrap:wrap;align-items:center;gap:0.25rem}
.rs-artifact-content{min-width:0;overflow:auto;padding:1rem;font-size:0.875rem;line-height:1.45;outline-color:var(--text);outline-offset:-2px}
.rs-artifact-footer{padding:0.75rem 1rem;border-top-width:1px;border-top-style:solid;border-top-color:var(--divider);color:var(--text-secondary);font-size:0.75rem;line-height:1.45}

