"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Badge } from "./badge";
import { Button } from "./button";
import { Collapsible } from "./collapsible";
import { SnippetCopy } from "./snippet";

export interface CommitFile { path: string; previousPath?: string; status: "added" | "modified" | "deleted" | "renamed"; additions?: number; deletions?: number }
export interface CommitProps extends Omit<React.HTMLAttributes<HTMLElement>, "onCopy" | "title"> {
  hash: string;
  message: string;
  author?: React.ReactNode;
  avatar?: React.ReactNode;
  /** ISO date or Date; a supplied timeLabel can use the application's locale or relative clock. */
  timestamp?: string | Date;
  timeLabel?: string;
  files?: CommitFile[];
  defaultOpen?: boolean;
  onFileSelect?: (file: CommitFile) => void;
  onCopy?: (hash: string) => void | Promise<void>;
}
const styles = stylex.create({
  root: { minWidth: 0, width: "100%", borderWidth: vlak.hairline, borderStyle: "solid", borderColor: { default: vlak.divider, [mq.forcedColors]: "CanvasText" }, borderRadius: vlak.radiusSm, color: vlak.ink, backgroundColor: vlak.paper, fontSize: "0.875rem", lineHeight: 1.45 },
  header: { display: "flex", flexWrap: "wrap", alignItems: "center", gap: "0.75rem", padding: "0.75rem 1rem" },
  heading: { display: "grid", gap: "0.25rem", minWidth: 0, flex: "1 1 auto", overflowWrap: "anywhere" },
  message: { fontWeight: 600 },
  metadata: { display: "flex", flexWrap: "wrap", alignItems: "center", gap: "0.5rem", color: vlak.gray, fontSize: "0.75rem" },
  content: { padding: "0 1rem 1rem", minWidth: 0 },
  list: { listStyle: "none", padding: 0, margin: 0, color: vlak.ink },
  file: { display: "flex", flexWrap: "wrap", alignItems: "center", gap: "0.5rem", minWidth: 0, paddingBlock: "0.5rem", borderTopWidth: vlak.hairline, borderTopStyle: "solid", borderTopColor: vlak.divider },
  path: { minWidth: 0, flex: "1 1 auto", overflowWrap: "anywhere", fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace", textAlign: "start" },
  count: { color: vlak.gray, fontSize: "0.75rem", fontVariantNumeric: "tabular-nums" },
});

/** Supplied commit metadata and changed files with exact hash copy and optional file navigation. */
export const Commit = React.forwardRef<HTMLElement, CommitProps>(function Commit({ hash, message, author, avatar, timestamp, timeLabel, files = [], defaultOpen = false, onFileSelect, onCopy, children, className, style, ...props }, ref) {
  const parsed = timestamp == null ? undefined : new Date(timestamp);
  const iso = parsed && Number.isFinite(parsed.getTime()) ? parsed.toISOString() : undefined;
  const root = rs(["rs-commit", className], styles.root);
  const header = rs(["rs-commit-header"], styles.header);
  const heading = rs(["rs-commit-heading"], styles.heading);
  const messageStyle = rs(["rs-commit-message"], styles.message);
  const metadata = rs(["rs-commit-metadata"], styles.metadata);
  const content = rs(["rs-commit-content"], styles.content);
  const list = rs(["rs-commit-list"], styles.list);
  const fileStyle = rs(["rs-commit-file"], styles.file);
  const path = rs(["rs-commit-path"], styles.path);
  const count = rs(["rs-commit-count"], styles.count);
  return <article aria-label={`Commit ${hash.slice(0, 7)}`} {...props} ref={ref} className={root.className} style={{ ...root.style, ...style }}>
    <header {...header}>{avatar}<div {...heading}><span {...messageStyle}>{message}</span><div {...metadata}><code>{hash.slice(0, 7)}</code>{author}{iso && <time dateTime={iso}>{timeLabel ?? iso.replace("T", " ").slice(0, 16) + " UTC"}</time>}</div></div><SnippetCopy value={hash} label="Copy commit hash" onCopy={onCopy} /></header>
    <div {...content}><Collapsible title={`${files.length} changed ${files.length === 1 ? "file" : "files"}`} defaultOpen={defaultOpen}><ul {...list}>{files.map(file => <li key={file.path} {...fileStyle}>
      <Badge variant="muted">{file.status}</Badge>{onFileSelect ? <Button {...path} type="button" variant="subtle" onClick={() => onFileSelect(file)}>{file.path}</Button> : <code {...path}>{file.path}</code>}
      {file.previousPath && <span {...count}>from {file.previousPath}</span>}{file.additions != null && <span {...count}>{file.additions} additions</span>}{file.deletions != null && <span {...count}>{file.deletions} deletions</span>}
    </li>)}</ul>{files.length === 0 && <p {...count}>No file changes supplied.</p>}</Collapsible>{children}</div>
  </article>;
});

/* ── commit: generated from packages/react/src/components/commit.tsx ── */
.rs-commit{min-width:0;width:100%;border-width:1px;border-style:solid;border-color:var(--divider);border-radius:var(--radius-sm);color:var(--text);background-color:var(--bg);font-size:0.875rem;line-height:1.45}
@media (forced-colors: active){.rs-commit{border-color:CanvasText}}
.rs-commit-header{display:flex;flex-wrap:wrap;align-items:center;gap:0.75rem;padding:0.75rem 1rem}
.rs-commit-heading{display:grid;gap:0.25rem;min-width:0;flex:1 1 auto;overflow-wrap:anywhere}
.rs-commit-message{font-weight:600}
.rs-commit-metadata{display:flex;flex-wrap:wrap;align-items:center;gap:0.5rem;color:var(--text-secondary);font-size:0.75rem}
.rs-commit-content{padding:0 1rem 1rem;min-width:0}
.rs-commit-list{list-style:none;padding:0;margin:0;color:var(--text)}
.rs-commit-file{display:flex;flex-wrap:wrap;align-items:center;gap:0.5rem;min-width:0;padding-block:0.5rem;border-top-width:1px;border-top-style:solid;border-top-color:var(--divider)}
.rs-commit-path{min-width:0;flex:1 1 auto;overflow-wrap:anywhere;font-family:ui-monospace, SFMono-Regular, Menlo, monospace;text-align:start}
.rs-commit-count{color:var(--text-secondary);font-size:0.75rem;font-variant-numeric:tabular-nums}

"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Button } from "./button";
import { SnippetCopy } from "./snippet";

export interface EnvironmentVariable { name: string; value: string; required?: boolean; description?: string }
export interface EnvironmentVariablesProps extends Omit<React.HTMLAttributes<HTMLElement>, "onCopy" | "title"> {
  variables: EnvironmentVariable[];
  title?: React.ReactNode;
  showValues?: boolean;
  defaultShowValues?: boolean;
  onShowValuesChange?: (show: boolean) => void;
  onCopy?: (value: string) => void | Promise<void>;
}

/** POSIX shell-safe assignments. Invalid names are rejected rather than emitted as executable shell text. */
export function formatEnvironmentExports(variables: EnvironmentVariable[]): string {
  return variables.map(({ name, value }) => {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) throw new Error("Invalid environment variable name");
    return `export ${name}='${value.replaceAll("'", "'\\''")}'`;
  }).join("\n");
}
const styles = stylex.create({
  root: { minWidth: 0, width: "100%", borderWidth: vlak.hairline, borderStyle: "solid", borderColor: { default: vlak.divider, [mq.forcedColors]: "CanvasText" }, borderRadius: vlak.radiusSm, color: vlak.ink, backgroundColor: vlak.paper },
  header: { display: "flex", flexWrap: "wrap", alignItems: "center", gap: "0.5rem", padding: "0.5rem 1rem", borderBottomWidth: vlak.hairline, borderBottomStyle: "solid", borderBottomColor: vlak.divider },
  title: { flex: "1 1 auto", fontSize: "0.875rem", lineHeight: 1.45, fontWeight: 600 },
  list: { margin: 0, padding: "0 1rem" },
  row: { display: "grid", gridTemplateColumns: { default: "minmax(0, 1fr) minmax(0, 1fr) auto", [mq.phone]: "minmax(0, 1fr) auto" }, alignItems: "center", gap: "0.5rem", paddingBlock: "0.5rem", borderBottomWidth: vlak.hairline, borderBottomStyle: "solid", borderBottomColor: vlak.divider },
  name: { margin: 0, minWidth: 0, overflowWrap: "anywhere", fontSize: "0.875rem", lineHeight: 1.45 },
  value: { margin: 0, minWidth: 0, overflowWrap: "anywhere", fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace", fontSize: "0.875rem", lineHeight: 1.45, gridColumn: { default: "auto", [mq.phone]: "1 / 2" } },
  controls: { display: "flex", flexWrap: "wrap", justifyContent: "flex-end", gap: "0.25rem", margin: 0, gridColumn: { default: "auto", [mq.phone]: "2 / 3" }, gridRow: { default: "auto", [mq.phone]: "1 / 3" } },
  note: { display: "block", margin: 0, color: vlak.gray, fontSize: "0.75rem", lineHeight: 1.45 },
  footer: { display: "flex", flexWrap: "wrap", alignItems: "center", gap: "0.5rem", padding: "0.5rem 1rem" },
});

/** Masked values with deliberate reveal and exact-value/export copy actions. */
export const EnvironmentVariables = React.forwardRef<HTMLElement, EnvironmentVariablesProps>(function EnvironmentVariables({ variables, title = "Environment variables", showValues, defaultShowValues = false, onShowValuesChange, onCopy, className, style, "aria-label": label, "aria-labelledby": labelledBy, ...props }, ref) {
  const titleId = React.useId();
  const [innerShow, setInnerShow] = React.useState(defaultShowValues);
  const [revealed, setRevealed] = React.useState<Record<string, string>>({});
  const visible = showValues ?? innerShow;
  const setVisible = (show: boolean) => { if (showValues === undefined) setInnerShow(show); setRevealed({}); onShowValuesChange?.(show); };
  let exports = "";
  let validNames = true;
  try { exports = formatEnvironmentExports(variables); } catch { validNames = false; }
  const root = rs(["rs-environment-variables", className], styles.root);
  const header = rs(["rs-environment-variables-header"], styles.header);
  const titleStyle = rs(["rs-environment-variables-title"], styles.title);
  const list = rs(["rs-environment-variables-list"], styles.list);
  const row = rs(["rs-environment-variables-row"], styles.row);
  const name = rs(["rs-environment-variables-name"], styles.name);
  const valueStyle = rs(["rs-environment-variables-value"], styles.value);
  const controls = rs(["rs-environment-variables-controls"], styles.controls);
  const note = rs(["rs-environment-variables-note"], styles.note);
