  maskedIdentifier?: string | null;
  identifierLabel?: string;
  issuer?: React.ReactNode;
  issuedLabel?: React.ReactNode;
  expiresLabel?: React.ReactNode;
  /** Supplied record or verification status. Expiry is never calculated. */
