  const y = (value: number) => 216 - fraction(value, vertical) * 184;
  const axisName = (name: string, unit?: string) => unit ? `${name} (${unit})` : name;
  const xTitle = axisName(xLabel, xUnit);
  const yTitle = axisName(yLabel, yUnit);
