.rs-field-label.rs-input-label{font-size:0.75rem;font-weight:600;color:var(--text-secondary);letter-spacing:-0.01em;line-height:16px}
@media (max-width: 640px){.rs-field-label.rs-input-label{font-size:var(--control-label)}}
