import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak } from "./tokens.stylex";
import { rs } from "./rs";

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  max?: number;
  /** Label above the bar; it names the bar. The percentage lives here, never inside the bar. */
  label?: React.ReactNode;
}

const styles = stylex.create({
  head: {
    display: "flex",
    justifyContent: "space-between",
    fontSize: "0.75rem",
    fontWeight: 500,
    color: vlak.gray,
    letterSpacing: "-0.01em",
    marginBottom: "0.4375rem",
  },
  bar: {
    height: "0.25rem",
    backgroundColor: vlak.dividerSubtle,
    borderRadius: 2,
    overflow: "hidden",
  },
  fill: {
    display: "block",
    height: "100%",
    backgroundColor: vlak.ink,
    borderRadius: 2,
  },
});

export const Progress = React.forwardRef<HTMLDivElement, ProgressProps>(function Progress({
  value,
  max = 100,
  label,
  className,
  style,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}, ref) {
  const labelId = React.useId();
  const now = Math.min(max, Math.max(0, value));
  const pct = Math.min(100, Math.max(0, max === 0 ? 0 : (value / max) * 100));
  const head = rs(["rs-progress-head"], styles.head);
  const bar = rs(["rs-progress"], styles.bar);
  const fill = rs(["rs-progress-fill"], styles.fill);
  const labelledBy = ariaLabelledBy ?? (ariaLabel == null && label != null ? labelId : undefined);
  return (
    <div ref={ref} {...props} className={className} style={style}>
      {label != null && (
        <div className={head.className} style={head.style}>
          <span id={labelId}>{label}</span>
          <span>{Math.round(pct)}%</span>
        </div>
      )}
      <div
        className={bar.className}
        style={bar.style}
        role="progressbar"
        aria-label={ariaLabel}
        aria-labelledby={labelledBy}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={now}
        aria-valuetext={`${Math.round(pct)}%`}
      >
        <span className={fill.className} style={{ ...fill.style, width: `${pct}%` }} />
      </div>
    </div>
  );
});

/* ── progress: generated from packages/react/src/components/progress.tsx ── */
.rs-progress-head{display:flex;justify-content:space-between;font-size:0.75rem;font-weight:500;color:var(--text-secondary);letter-spacing:-0.01em;margin-bottom:0.4375rem}
.rs-progress{height:0.25rem;background-color:var(--divider-subtle);border-radius:2px;overflow:hidden}
.rs-progress-fill{display:block;height:100%;background-color:var(--text);border-radius:2px}

