"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Icon } from "./icons";
import { Checkbox } from "./checkbox";
import { Input } from "./input";

export interface DataTableColumn<Row> {
  key: string;
  header: React.ReactNode;
  /** Cell renderer; defaults to the row's value at `key`. */
  render?: (row: Row) => React.ReactNode;
  sortable?: boolean;
  /** Sort accessor; defaults to the row's value at `key`. */
  sortValue?: (row: Row) => string | number;
}

export interface DataTableProps<Row> extends React.HTMLAttributes<HTMLDivElement> {
  columns: Array<DataTableColumn<Row>>;
  rows: Row[];
  rowKey?: (row: Row, index: number) => React.Key;
  emptyLabel?: React.ReactNode;
  caption?: string;
  sort?: DataTableSort | null;
  defaultSort?: DataTableSort | null;
  onSortChange?: (sort: DataTableSort | null) => void;
  selectable?: boolean;
  selectedKeys?: React.Key[];
  defaultSelectedKeys?: React.Key[];
  onSelectionChange?: (keys: React.Key[]) => void;
  filterable?: boolean;
  filter?: string;
  defaultFilter?: string;
  onFilterChange?: (filter: string) => void;
  filterRow?: (row: Row, filter: string) => boolean;
}

export interface DataTableSort { key: string; dir: "asc" | "desc" }

const styles = stylex.create({
  scroll: { width: "100%", overflowX: "auto" },
  table: {
    width: {
      default: "100%",
      [mq.phone]: "100%",
    },
    borderCollapse: "collapse",
    marginTop: "1rem",
    marginBottom: "1.5rem",
    marginInlineStart: {
      default: 0,
      [mq.phone]: 0,
    },
    marginInlineEnd: {
      default: 0,
      [mq.phone]: 0,
    },
    fontSize: {
      default: "0.875rem",
      [mq.phone]: "1rem",
    },
  },
  th: {
    textAlign: {
      default: "start",
      ":last-child": "end",
    },
    fontWeight: 600,
    color: vlak.ink,
    letterSpacing: "-0.01em",
    paddingTop: {
      default: "0.625rem",
      [mq.phone]: "0.875rem",
    },
    paddingInlineEnd: {
      default: "1rem",
      [mq.phone]: "0.75rem",
      ":last-child": {
        default: 20,
        [mq.phone]: vlak.pad,
      },
    },
    paddingBottom: {
      default: "0.625rem",
      [mq.phone]: "0.875rem",
    },
    paddingInlineStart: {
      default: "0.75rem",
      [mq.phone]: "0.75rem",
      ":first-child": {
        default: 20,
        [mq.phone]: vlak.pad,
      },
    },
    borderBottomWidth: 2,
    borderBottomStyle: "solid",
    borderBottomColor: vlak.divider,
    fontSize: {
      default: "0.8125rem",
      [mq.phone]: "0.9375rem",
    },
  },
  td: {
    paddingTop: {
      default: "0.625rem",
      [mq.phone]: "0.875rem",
    },
    paddingInlineEnd: {
      default: "1rem",
      [mq.phone]: "0.75rem",
      ":last-child": {
        default: 20,
        [mq.phone]: vlak.pad,
      },
    },
    paddingBottom: {
      default: "0.625rem",
      [mq.phone]: "0.875rem",
    },
    paddingInlineStart: {
      default: "0.75rem",
      [mq.phone]: "0.75rem",
      ":first-child": {
        default: 20,
        [mq.phone]: vlak.pad,
      },
    },
    color: vlak.gray,
    fontWeight: 500,
    letterSpacing: "-0.01em",
    borderBottomWidth: vlak.hairline,
    borderBottomStyle: "solid",
    borderBottomColor: vlak.divider,
    verticalAlign: "top",
    fontSize: {
      default: null,
      [mq.phone]: "1rem",
    },
    textAlign: {
      default: null,
      ":last-child": "end",
    },
  },
  tdAlt: {
    backgroundColor: vlak.tableAlt,
  },
  selected: { backgroundColor: vlak.controlFill, color: vlak.ink },
  sort: {
    backgroundColor: "transparent",
    borderWidth: 0,
    borderStyle: "none",
    padding: 0,
    fontFamily: "inherit",
    fontSize: "inherit",
    fontWeight: 600,
    letterSpacing: "inherit",
    color: "inherit",
    cursor: "pointer",
    display: "inline-flex",
    alignItems: "center",
    gap: "0.3125rem",
    minHeight: vlak.hit,
    minWidth: vlak.hit,
    outlineWidth: {
      default: null,
